#include "streaming_input.hpp"
static Tensor slice(const Vec&v,int n,bool resize){if(!resize){Tensor t(1,128,128);std::copy(v.begin()+n*16384,v.begin()+(n+1)*16384,t.v.begin());return t;}Tensor t(3,224,224);const float means[]={.485f,.456f,.406f},stds[]={.229f,.224f,.225f};for(int y=0;y<224;y++)for(int x=0;x<224;x++){float fy=(y+.5f)*(128.f/224.f)-.5f,fx=(x+.5f)*(128.f/224.f)-.5f;int iy=int(std::floor(fy)),ix=int(std::floor(fx));float wy=fy-iy,wx=fx-ix;int y0=std::max(0,iy),y1=std::min(127,iy+1),x0=std::max(0,ix),x1=std::min(127,ix+1);const float*p=v.data()+n*16384;float z=(p[y0*128+x0]*(1-wx)+p[y0*128+x1]*wx)*(1-wy)+(p[y1*128+x0]*(1-wx)+p[y1*128+x1]*wx)*wy;z*=256.f/255.f;for(int c=0;c<3;c++)t.v[(c*224+y)*224+x]=(z-means[c])/stds[c];}return t;}
